import{_ as a,c as t,o as i,j as n,Y as o,t as r}from"./chunks/framework.D-NV0Bun.js";const u=JSON.parse('{"title":"x25 | x-cmd man (man7) | ITU-T X.25 / ISO/IEC 8208 protocol interface","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | x25 - ITU-T X.25 / ISO/IEC 8208 protocol interface","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"x25 | x-cmd man (man7) | ITU-T X.25 / ISO/IEC 8208 protocol interface"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | x25 - ITU-T X.25 / ISO/IEC 8208 protocol interface"}]]},"headers":[],"params":{"isMan":true,"man":"x25","category":"man7","desc":"ITU-T X.25 / ISO/IEC 8208 protocol interface"},"relativePath":"man7/x25.md","filePath":"man7/[man].md"}'),h={name:"man7/x25.md"},l={class:"visually-hidden"};function d(s,e,p,c,k,m){return i(),t("div",null,[n("h1",l,r(s.$params.man),1),e[0]||(e[0]=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>x25 - ITU-T X.25 / ISO/IEC 8208 protocol interface</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#include &lt;sys/socket.h&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#include &lt;linux/x25.h&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">x25_socket</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> socket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AF_X25,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SOCK_SEQPACKET,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>X25 sockets provide an interface to the X.25 packet layer protocol. This allows applications to communicate over a public X.25 data network as standardized by International Telecommunication Union&#39;s recommendation X.25 (X.25 DTE-DCE mode). X25 sockets can also be used for communication without an intermediate X.25 network (X.25 DTE-DTE mode) as described in ISO/IEC 8208.</p><p>Message boundaries are preserved --- a <strong>read</strong>(2) from a socket will retrieve the same chunk of data as output with the corresponding <strong>write</strong>(2) to the peer socket. When necessary, the kernel takes care of segmenting and reassembling long messages by means of the X.25 M-bit. There is no hard-coded upper limit for the message size. However, reassembling of a long message might fail if there is a temporary lack of system resources or when other constraints (such as socket memory or buffer size limits) become effective. If that occurs, the X.25 connection will be reset.</p><h3 id="socket-addresses" tabindex="-1">Socket addresses <a class="header-anchor" href="#socket-addresses" aria-label="Permalink to &quot;Socket addresses&quot;">​</a></h3><p>The <strong>AF_X25</strong> socket address family uses the <em>struct sockaddr_x25</em> for representing network addresses as defined in ITU-T recommendation X.121.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">struct</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sockaddr_x25</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sa_family_t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sx25_family</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> must</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> be</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AF_X25</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">x25_address</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sx25_addr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> X.121</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Address</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p><em>sx25_addr</em> contains a char array <em>x25_addr[]</em> to be interpreted as a null-terminated string. <em>sx25_addr.x25_addr[]</em> consists of up to 15 (not counting the terminating null byte) ASCII characters forming the X.121 address. Only the decimal digit characters from &#39;0&#39; to &#39;9&#39; are allowed.</p><h3 id="socket-options" tabindex="-1">Socket options <a class="header-anchor" href="#socket-options" aria-label="Permalink to &quot;Socket options&quot;">​</a></h3><p>The following X.25-specific socket options can be set by using <strong>setsockopt</strong>(2) and read with <strong>getsockopt</strong>(2) with the <em>level</em> argument set to <strong>SOL_X25</strong>.</p><dl><dt><strong>X25_QBITINCL</strong></dt><dd>Controls whether the X.25 Q-bit (Qualified Data Bit) is accessible by the user. It expects an integer argument. If set to 0 (default), the Q-bit is never set for outgoing packets and the Q-bit of incoming packets is ignored. If set to 1, an additional first byte is prepended to each message read from or written to the socket. For data read from the socket, a 0 first byte indicates that the Q-bits of the corresponding incoming data packets were not set. A first byte with value 1 indicates that the Q-bit of the corresponding incoming data packets was set. If the first byte of the data written to the socket is 1, the Q-bit of the corresponding outgoing data packets will be set. If the first byte is 0, the Q-bit will not be set.</dd></dl><h2 id="versions" tabindex="-1">VERSIONS <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;VERSIONS&quot;">​</a></h2><p>The AF_X25 protocol family is a new feature of Linux 2.2.</p><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>Plenty, as the X.25 PLP implementation is <strong>CONFIG_EXPERIMENTAL</strong>.</p><p>This man page is incomplete.</p><p>There is no dedicated application programmer&#39;s header file yet; you need to include the kernel header file <em>&lt;linux/x25.h&gt;</em>. <strong>CONFIG_EXPERIMENTAL</strong> might also imply that future versions of the interface are not binary compatible.</p><p>X.25 N-Reset events are not propagated to the user process yet. Thus, if a reset occurred, data might be lost without notice.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>socket</strong>(2), <strong>socket</strong>(7)</p><p>Jonathan Simon Naylor: &quot;The Re-Analysis and Re-Implementation of X.25.&quot; The URL is <a href="ftp://ftp.pspt.fi/pub/ham/linux/ax25/x25doc.tgz" target="_blank" rel="noreferrer"></a>.</p>`,24))])}const f=a(h,[["render",d]]);export{u as __pageData,f as default};
